private val v3Client = createSupabaseClient(BuildConfig.SUPABASE_URL, BuildConfig.SUPABASE_PUBLISHABLE_KEY) { install(Postgrest) }
private val Bg = Color(0xFFF4F7FB)
private val Navy = Color(0xFF021024)
private val Blue = Color(0xFF165DDA)
private val SoftBlue = Color(0xFFEAF2FF)
private val Text2 = Color(0xFF64748B)
private val Green = Color(0xFF12966F)
private val Amber = Color(0xFFE39A00)
private val Red = Color(0xFFD94A4A)
private val menus = listOf("Dashboard","Penjualan","Pesanan","Produk","Stok","Pelanggan","Supplier","Pembelian","Piutang","Laporan","Pembayaran","Pengaturan")

private fun idr(v: Long): String = "Rp " + v.toString().reversed().chunked(3).joinToString(".").reversed()
private fun statusColor(s: String): Color = when (s.uppercase()) { "PAID","COMPLETED","OK" -> Green; "PENDING","OPEN","PARTIAL","LOW" -> Amber; "FAILED","EXPIRED","CANCELLED","OVERDUE","VOID" -> Red; else -> Text2 }
private fun iconFor(s: String): String = when (s) { "Dashboard"->"⌂"; "Penjualan"->"▣"; "Pesanan"->"☷"; "Produk"->"□"; "Stok"->"◫"; "Pelanggan"->"♙"; "Supplier"->"♙"; "Pembelian"->"↳"; "Piutang"->"▤"; "Laporan"->"▥"; "Pembayaran"->"◉"; "Pengaturan"->"⚙"; else->"•" }

@Composable fun OwnerPosAppV3() {
    var page by remember { mutableStateOf("Dashboard") }
    var more by remember { mutableStateOf(false) }
    val tablet = LocalConfiguration.current.screenWidthDp >= 600
    MaterialTheme(colorScheme = lightColorScheme(primary = Blue, background = Bg, surface = Color.White)) {
        Surface(Modifier.fillMaxSize(), color = Bg) {
            if (tablet) Row(Modifier.fillMaxSize()) {
                OwnerSidebarV3(page) { page = it }
                Box(Modifier.weight(1f).fillMaxSize()) { V3Page(page) }
            } else Column(Modifier.fillMaxSize()) {
                Box(Modifier.weight(1f).fillMaxWidth()) { V3Page(page) }
                BottomNavV3(page, { page = it }, { more = true })
                if (more) MoreSheetV3(page, { page = it; more = false }) { more = false }
            }
        }
    }
}

@Composable private fun OwnerSidebarV3(selected: String, onSelect: (String)->Unit) {
    Surface(Modifier.width(238.dp).fillMaxHeight(), color = Navy) {
        Column(Modifier.fillMaxHeight().padding(16.dp), verticalArrangement = Arrangement.spacedBy(5.dp)) {
            Row(Modifier.padding(6.dp, 7.dp, 6.dp, 16.dp), verticalAlignment = Alignment.CenterVertically) {
                Box(Modifier.size(40.dp).clip(RoundedCornerShape(12.dp)).background(Blue), contentAlignment = Alignment.Center) { Text("P", color=Color.White, fontSize=20.sp, fontWeight=FontWeight.ExtraBold) }
                Column(Modifier.padding(start=10.dp)) { Text("POS QRIS", color=Color.White, fontWeight=FontWeight.ExtraBold, fontSize=18.sp); Text("Owner workspace", color=Color(0xFF9FB3CC), fontSize=11.sp) }
            }
            menus.forEach { m ->
                val active = selected == m
                Surface(Modifier.fillMaxWidth().clickable { onSelect(m) }, RoundedCornerShape(12.dp), if (active) Blue else Color.Transparent) {
                    Row(Modifier.padding(horizontal=12.dp, vertical=10.dp), verticalAlignment=Alignment.CenterVertically) { Text(iconFor(m), Modifier.width(28.dp), color=if(active) Color.White else Color(0xFFB8C8DE)); Text(m, color=if(active) Color.White else Color(0xFFE7EEF8), fontWeight=if(active) FontWeight.Bold else FontWeight.Medium) }
                }
            }
            Spacer(Modifier.weight(1f))
            Surface(RoundedCornerShape(14.dp), color=Color(0xFF0A1D35)) { Column(Modifier.padding(13.dp)) { Text("OWNER", color=Color(0xFFC1E8FF), fontSize=11.sp, fontWeight=FontWeight.Bold); Text("Akses seluruh menu", color=Color.White, fontSize=13.sp); Text("Data live dari Supabase", color=Color(0xFF9FB3CC), fontSize=11.sp) } }
        }
    }
}

@Composable private fun BottomNavV3(selected:String,onSelect:(String)->Unit,onMore:()->Unit) {
    val main = listOf("Dashboard","Penjualan","Produk","Stok")
    Surface(Modifier.fillMaxWidth().navigationBarsPadding(), color=Color.White, shadowElevation=14.dp) {
        Row(Modifier.fillMaxWidth().padding(7.dp), horizontalArrangement=Arrangement.spacedBy(4.dp)) {
            main.forEach { m -> NavButtonV3(m, selected==m, Modifier.weight(1f)) { onSelect(m) } }
            NavButtonV3("Lainnya", selected !in main, Modifier.weight(1f)) { onMore() }
        }
    }
}
@Composable private fun NavButtonV3(label:String, active:Boolean, modifier:Modifier, onClick:()->Unit) { Surface(modifier.clickable{onClick()}, RoundedCornerShape(12.dp), if(active) SoftBlue else Color.Transparent) { Column(Modifier.padding(vertical=6.dp), horizontalAlignment=Alignment.CenterHorizontally) { Text(if(label=="Lainnya") "•••" else iconFor(label), color=if(active) Blue else Text2, fontSize=17.sp); Text(label, color=if(active) Blue else Text2, fontSize=10.sp, fontWeight=if(active) FontWeight.Bold else FontWeight.Normal) } } }

@Composable private fun MoreSheetV3(selected:String,onSelect:(String)->Unit,onDismiss:()->Unit) { ModalBottomSheet(onDismissRequest=onDismiss, containerColor=Color.White) { Column(Modifier.fillMaxWidth().padding(18.dp)) { Text("Menu Owner", color=Navy, fontSize=22.sp, fontWeight=FontWeight.ExtraBold); Text("Semua menu menggunakan data Supabase", color=Text2, fontSize=12.sp, modifier=Modifier.padding(top=3.dp,bottom=12.dp)); menus.drop(4).forEach { m -> Surface(Modifier.fillMaxWidth().clickable{onSelect(m)}, RoundedCornerShape(12.dp), if(m==selected) SoftBlue else Color.Transparent) { Row(Modifier.padding(13.dp),verticalAlignment=Alignment.CenterVertically){Text(iconFor(m),Modifier.width(32.dp),color=Blue);Text(m,color=Navy,fontWeight=if(m==selected) FontWeight.Bold else FontWeight.Medium)}} } } } }

@Composable private fun V3Page(page:String) { when(page) { "Dashboard"->DashboardV3(); "Penjualan"->SalesV3(); "Pesanan"->OrdersV3(); "Produk"->ProductsV3(); "Stok"->StockV3(); "Pelanggan"->CustomersV3(); "Supplier"->SuppliersV3(); "Pembelian"->PurchasesV3(); "Piutang"->ReceivablesV3(); "Laporan"->ReportsV3(); "Pembayaran"->PaymentsV3(); "Pengaturan"->SettingsV3() } }

