@Composable private fun DashboardV3(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var sales by remember{mutableStateOf<List<SaleRow>>(emptyList())};var stock by remember{mutableStateOf<List<Stock>>(emptyList())};var business by remember{mutableStateOf<Business?>(null)};var customers by remember{mutableStateOf<List<Customer>>(emptyList())};fun load() { } LaunchedEffect(Unit){while(true){runCatching{business=v3Client.from("businesses").select{filter{eq("is_active",true)}}.decodeList<Business>().firstOrNull();products=v3Client.from("products").select{filter{eq("is_active",true)}}.decodeList<Product>();sales=v3Client.from("sales").select().decodeList<SaleRow>();stock=v3Client.from("stock_balances").select().decodeList<Stock>();customers=v3Client.from("customers").select{filter{eq("is_active",true)}}.decodeList<Customer>()};delay(5000)}};val today=LocalDate.now(ZoneId.of("Asia/Jakarta")).toString();val todaySales=sales.filter{it.sale_date.startsWith(today)&&it.status.uppercase()=="COMPLETED"};val low=stock.count{x->products.firstOrNull{p->p.id==x.product_id}?.let{p->x.qty_base<=p.min_stock}==true};V3Shell("Beranda","${business?.name?:"Toko"} • Owner",::load){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){StatV3("Penjualan hari ini",idr(todaySales.sumOf{it.total_amount}),"${todaySales.size} transaksi",Modifier.weight(1.3f));StatV3("Produk",products.size.toString(),"SKU aktif",Modifier.weight(1f));StatV3("Pelanggan",customers.size.toString(),"aktif",Modifier.weight(1f));StatV3("Stok menipis",low.toString(),"perlu perhatian",Modifier.weight(1f))};Row(Modifier.weight(1f),horizontalArrangement=Arrangement.spacedBy(12.dp)){Card(Modifier.weight(1.4f).fillMaxHeight(),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(15.dp)){Text("Transaksi terbaru",color=Navy,fontWeight=FontWeight.ExtraBold);LazyColumn{items(sales.takeLast(10).reversed()){sale->Row(Modifier.fillMaxWidth().padding(vertical=9.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(sale.sale_no,fontWeight=FontWeight.SemiBold,color=Navy);Text(sale.sale_date.replace("T"," ").take(16),fontSize=10.sp,color=Text2)};Text(idr(sale.total_amount),fontWeight=FontWeight.Bold,color=Navy);Spacer(Modifier.width(10.dp));BadgeV3(sale.status)}}}}};Card(Modifier.weight(1f).fillMaxHeight(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(Navy)){Column(Modifier.padding(18.dp)){Text("Owner overview",color=Color(0xFFC1E8FF),fontSize=11.sp,fontWeight=FontWeight.Bold);Text("Kontrol bisnis",color=Color.White,fontSize=24.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.padding(top=4.dp));Text("Produk, stok, pelanggan, pembayaran, pembelian, piutang, laporan dan pengaturan tersedia dari satu workspace.",color=Color(0xFFCBD7E6),fontSize=12.sp,modifier=Modifier.padding(top=7.dp))}}}}

@Composable private fun SalesV3(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var prices by remember{mutableStateOf<List<ProductPrice>>(emptyList())};var categories by remember{mutableStateOf<List<Category>>(emptyList())};var stock by remember{mutableStateOf<List<Stock>>(emptyList())};var branch by remember{mutableStateOf<Branch?>(null)};var location by remember{mutableStateOf<Location?>(null)};var cart by remember{mutableStateOf<List<CartLine>>(emptyList())};var search by remember{mutableStateOf("")};var category by remember{mutableStateOf("Semua")};var cartSheet by remember{mutableStateOf(false)};var paySheet by remember{mutableStateOf(false)};var message by remember{mutableStateOf<String?>(null)};fun load(){} LaunchedEffect(Unit){runCatching{val b=v3Client.from("businesses").select{filter{eq("is_active",true)}}.decodeList<Business>().first();branch=v3Client.from("branches").select{filter{eq("business_id",b.id);eq("is_active",true)}}.decodeList<Branch>().first();location=v3Client.from("locations").select{filter{eq("branch_id",branch!!.id);eq("is_active",true)}}.decodeList<Location>().first();products=v3Client.from("products").select{filter{eq("business_id",b.id);eq("is_active",true)}}.decodeList<Product>();categories=v3Client.from("categories").select{filter{eq("business_id",b.id);eq("is_active",true)}}.decodeList<Category>();val pl=v3Client.from("price_lists").select{filter{eq("business_id",b.id);eq("is_default",true);eq("is_active",true)}}.decodeList<PriceList>().firstOrNull();if(pl!=null)prices=v3Client.from("product_prices").select{filter{eq("price_list_id",pl.id)}}.decodeList<ProductPrice>();stock=v3Client.from("stock_balances").select().decodeList<Stock>()};};fun price(p:Product)=prices.filter{it.product_id==p.id}.minByOrNull{it.min_qty}?.price?:0;fun qty(p:Product)=stock.firstOrNull{it.product_id==p.id&&it.location_id==location?.id}?.qty_base?:0.0;val shown=products.filter{(search.isBlank()||it.name.contains(search,true)||it.sku.contains(search,true))&&(category=="Semua"||categories.firstOrNull{x->x.id==it.category_id}?.name==category)};val total=cart.sumOf{it.price*it.qty};V3Shell("Penjualan Baru","${branch?.name?:"Memuat cabang..."} • Kasir Owner",::load){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){OutlinedTextField(search,{search=it},Modifier.weight(1f),singleLine=true,shape=RoundedCornerShape(13.dp),label={Text("Cari produk / scan barcode")});AssistChip(onClick={},label={Text("Pelanggan Umum")})};Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){(listOf("Semua")+categories.map{it.name}).forEach{m->FilterChip(selected=category==m,onClick={category=m},label={Text(m,fontSize=11.sp)})}};Box(Modifier.weight(1f)){LazyVerticalGrid(columns=GridCells.Adaptive(minSize=145.dp),contentPadding=PaddingValues(bottom=90.dp),horizontalArrangement=Arrangement.spacedBy(10.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){items(shown){p->Card(Modifier.fillMaxWidth().clickable{val old=cart.firstOrNull{it.product.id==p.id};cart=if(old==null)cart+CartLine(p,price(p),1)else cart.map{if(it.product.id==p.id)it.copy(qty=it.qty+1)else it}},shape=RoundedCornerShape(17.dp)){Column(Modifier.padding(12.dp)){Box(Modifier.fillMaxWidth().height(80.dp).clip(RoundedCornerShape(13.dp)).background(SoftBlue),contentAlignment=Alignment.Center){Text(p.short_name?.take(2)?.uppercase()?:p.name.take(2).uppercase(),color=Blue,fontSize=23.sp,fontWeight=FontWeight.ExtraBold)};Text(p.name,color=Navy,fontWeight=FontWeight.Bold,maxLines=2,modifier=Modifier.padding(top=9.dp));Text(idr(price(p)),color=Blue,fontWeight=FontWeight.ExtraBold,fontSize=16.sp,modifier=Modifier.padding(top=3.dp));Text("Stok ${qty(p).toInt()}",color=Text2,fontSize=10.sp,modifier=Modifier.padding(top=3.dp))}}}}};Surface(Modifier.align(Alignment.BottomCenter).fillMaxWidth().padding(10.dp).clickable{cartSheet=true},RoundedCornerShape(17.dp),Blue,shadowElevation=10.dp){Row(Modifier.padding(horizontal=17.dp,vertical=13.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Keranjang • ${cart.sumOf{it.qty}} item",color=Color.White,fontWeight=FontWeight.Bold,fontSize=12.sp);Text(idr(total),color=Color.White,fontSize=20.sp,fontWeight=FontWeight.ExtraBold)};Text("Lihat keranjang  →",color=Color.White,fontWeight=FontWeight.Bold)}}};if(message!=null)Text(message!!,color=Red)};if(cartSheet)CartSheetV3(cart,{cart=it},total,{cartSheet=false;paySheet=true},{cartSheet=false});if(paySheet)PaymentSheetV3(total,branch,location,cart,{paySheet=false;cartSheet=false;message="Transaksi diproses"},{paySheet=false})}

@Composable private fun CartSheetV3(cart:List<CartLine>,onCart:(List<CartLine>)->Unit,total:Long,onPay:()->Unit,onClose:()->Unit){ModalBottomSheet(onDismissRequest=onClose,containerColor=Color.White){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("Detail Pesanan",color=Navy,fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text("${cart.sumOf{it.qty}} item",color=Text2,fontSize=12.sp,modifier=Modifier.padding(top=3.dp,bottom=12.dp));LazyColumn(Modifier.heightIn(max=390.dp)){items(cart){line->Row(Modifier.fillMaxWidth().padding(vertical=9.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(line.product.name,color=Navy,fontWeight=FontWeight.SemiBold);Text(idr(line.price),color=Text2,fontSize=11.sp)};Row(verticalAlignment=Alignment.CenterVertically){TextButton({onCart(cart.map{if(it.product.id==line.product.id)it.copy(qty=maxOf(0,it.qty-1))else it}.filter{it.qty>0})}){Text("−")};Text(line.qty.toString(),fontWeight=FontWeight.Bold);TextButton({onCart(cart.map{if(it.product.id==line.product.id)it.copy(qty=it.qty+1)else it})}){Text("+")}};Text(idr(line.price*line.qty),color=Navy,fontWeight=FontWeight.Bold,modifier=Modifier.padding(start=8.dp))}}};HorizontalDivider(Modifier.padding(vertical=8.dp));SummaryV3(total,0,0,total,0);Button(onPay,Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(14.dp)){Text("Lanjut Pembayaran",fontWeight=FontWeight.Bold)}}}}
@Composable private fun SummaryV3(sub:Long,discount:Long,tax:Long,total:Long,paid:Long){Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Subtotal",color=Text2);Text(idr(sub),color=Navy,fontWeight=FontWeight.SemiBold)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Diskon",color=Text2);Text(idr(discount),color=Navy)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Pajak",color=Text2);Text(idr(tax),color=Navy)};HorizontalDivider(Modifier.padding(vertical=4.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("TOTAL",color=Navy,fontSize=18.sp,fontWeight=FontWeight.ExtraBold);Text(idr(total),color=Blue,fontSize=20.sp,fontWeight=FontWeight.ExtraBold)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Dibayar",color=Text2);Text(idr(paid),color=Navy)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Kembalian",color=Text2);Text(idr(maxOf(0,paid-total)),color=Green,fontWeight=FontWeight.Bold)}}}

@Composable private fun PaymentSheetV3(total:Long,branch:Branch?,location:Location?,cart:List<CartLine>,onDone:()->Unit,onClose:()->Unit){var method by remember{mutableStateOf("CASH")};var received by remember{mutableStateOf("")};var reference by remember{mutableStateOf("")};var processing by remember{mutableStateOf(false)};var result by remember{mutableStateOf<String?>(null)};val cash=received.toLongOrNull()?:0;val change=maxOf(0,cash-total);ModalBottomSheet(onDismissRequest=onClose,containerColor=Color.White){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("Pembayaran",color=Navy,fontSize=24.sp,fontWeight=FontWeight.ExtraBold);Text("Total pembayaran",color=Text2,fontSize=11.sp,modifier=Modifier.padding(top=3.dp));Text(idr(total),color=Blue,fontSize=30.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.padding(bottom=12.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("CASH","QRIS","TRANSFER").forEach{m->FilterChip(selected=method==m,onClick={method=m},label={Text(m)},modifier=Modifier.weight(1f))}};if(method=="CASH"){OutlinedTextField(received,{received=it.filter(Char::isDigit)},Modifier.fillMaxWidth().padding(top=12.dp),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),label={Text("Uang diterima")});SummaryV3(total,0,0,total,cash);if(cash>=total)Surface(Modifier.fillMaxWidth().padding(top=10.dp),RoundedCornerShape(14.dp),Green.copy(alpha=.1f)){Row(Modifier.padding(15.dp),horizontalArrangement=Arrangement.SpaceBetween){Text("KEMBALIAN",color=Green,fontWeight=FontWeight.Bold);Text(idr(change),color=Green,fontWeight=FontWeight.ExtraBold)}}};if(method=="TRANSFER")OutlinedTextField(reference,{reference=it},Modifier.fillMaxWidth().padding(top=12.dp),singleLine=true,label={Text("Referensi transfer")});if(method=="QRIS")Surface(Modifier.fillMaxWidth().padding(top=14.dp),RoundedCornerShape(17.dp),SoftBlue){Column(Modifier.fillMaxWidth().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("QRIS",color=Blue,fontSize=22.sp,fontWeight=FontWeight.ExtraBold);Text("Menunggu pembayaran",color=Text2,fontSize=12.sp);Text("Simulasi pembayaran",color=Text2,fontSize=11.sp,modifier=Modifier.padding(top=6.dp))}};if(result!=null)Text(result!!,color=Green,fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=8.dp));Button(enabled=!processing,onClick={processing=true;val b=branch;val l=location;if(b==null||l==null){result="Cabang/lokasi belum siap";processing=false}else{CoroutineScopeHolder.launch{runCatching{val itemsJson=cart.map{line->buildJsonObject{put("product_id",line.product.id);put("unit_id",line.product.base_unit_id);put("qty",line.qty);put("unit_price",line.price)}};val paymentsJson=buildJsonArrayCompat(method,total,reference,cash);v3Client.postgrest.rpc("checkout_sale_multi_payment",buildJsonObject{put("p_branch_id",b.id);put("p_location_id",l.id);put("p_customer_id",null as String?);put("p_items",itemsJson);put("p_payments",paymentsJson);put("p_idempotency_key",UUID.randomUUID().toString())}).decodeSingle<CheckoutResult>();result="Pembayaran berhasil";delay(400);onDone()}.onFailure{result=it.message?:"Checkout gagal"};processing=false}}}},Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(14.dp)){Text(if(processing)"Memproses..." else "Proses Pembayaran",fontWeight=FontWeight.Bold)}}}

private object CoroutineScopeHolder { private val scope = kotlinx.coroutines.CoroutineScope(kotlinx.coroutines.Dispatchers.Main.immediate); fun launch(block:suspend()->Unit)=scope.launch{block()} }
private fun buildJsonArrayCompat(method:String,total:Long,reference:String,cash:Long)=kotlinx.serialization.json.buildJsonArray{add(buildJsonObject{put("method_code",method);put("amount",if(method=="CASH")total else total);put("cash_received",if(method=="CASH")cash else 0);put("reference",reference)})}

@Composable private fun OrdersV3(){var sales by remember{mutableStateOf<List<SaleRow>>(emptyList())};LaunchedEffect(Unit){while(true){runCatching{sales=v3Client.from("sales").select().decodeList<SaleRow>()};delay(5000)}};V3Shell("Pesanan","Riwayat penjualan dari Supabase",{sales=sales}){LazyColumn{items(sales.reversed()){s->Card(Modifier.fillMaxWidth().padding(bottom=8.dp),shape=RoundedCornerShape(15.dp)){Row(Modifier.fillMaxWidth().padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(s.sale_no,color=Navy,fontWeight=FontWeight.Bold);Text(s.sale_date.replace("T"," ").take(16),fontSize=10.sp,color=Text2)};Text(idr(s.total_amount),color=Navy,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.width(10.dp));BadgeV3(s.status)}}}}}}

@Composable private fun ProductsV3(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var categories by remember{mutableStateOf<List<Category>>(emptyList())};var units by remember{mutableStateOf<List<UnitRow>>(emptyList())};var prices by remember{mutableStateOf<List<ProductPrice>>(emptyList())};var business by remember{mutableStateOf<Business?>(null)};var add by remember{mutableStateOf(false)};var query by remember{mutableStateOf("")};fun load(){} LaunchedEffect(Unit){while(true){runCatching{business=v3Client.from("businesses").select{filter{eq("is_active",true)}}.decodeList<Business>().first();products=v3Client.from("products").select{filter{eq("business_id",business!!.id);eq("is_active",true)}}.decodeList<Product>();categories=v3Client.from("categories").select{filter{eq("business_id",business!!.id);eq("is_active",true)}}.decodeList<Category>();units=v3Client.from("units").select{filter{eq("business_id",business!!.id)}}.decodeList<UnitRow>();val pl=v3Client.from("price_lists").select{filter{eq("business_id",business!!.id);eq("is_default",true);eq("is_active",true)}}.decodeList<PriceList>().firstOrNull();if(pl!=null)prices=v3Client.from("product_prices").select{filter{eq("price_list_id",pl.id)}}.decodeList<ProductPrice>()};delay(5000)}};V3Shell("Produk","Master produk live dari Supabase",::load){Row(verticalAlignment=Alignment.CenterVertically){OutlinedTextField(query,{query=it},Modifier.weight(1f),singleLine=true,shape=RoundedCornerShape(13.dp),label={Text("Cari SKU / nama produk")});Spacer(Modifier.width(8.dp));Button({add=true},shape=RoundedCornerShape(12.dp)){Text("+ Produk")}};LazyColumn{items(products.filter{query.isBlank()||it.name.contains(query,true)||it.sku.contains(query,true)}){p->val price=prices.filter{it.product_id==p.id}.minByOrNull{it.min_qty}?.price?:0;val cat=categories.firstOrNull{it.id==p.category_id}?.name?:"-";Card(Modifier.fillMaxWidth().padding(vertical=4.dp),shape=RoundedCornerShape(15.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(44.dp).clip(RoundedCornerShape(11.dp)).background(SoftBlue),contentAlignment=Alignment.Center){Text(p.name.take(1).uppercase(),color=Blue,fontWeight=FontWeight.ExtraBold)};Column(Modifier.weight(1f).padding(start=11.dp)){Text(p.name,color=Navy,fontWeight=FontWeight.Bold);Text("${p.sku} • $cat",color=Text2,fontSize=10.sp)};Text(idr(price),color=Blue,fontWeight=FontWeight.ExtraBold)}}}}};if(add)AddProductSheetV3(business,categories,units){add=false;products=emptyList()}{add=false}}}

@Composable private fun AddProductSheetV3(business:Business?,categories:List<Category>,units:List<UnitRow>,onSaved:()->Unit,onClose:()->Unit){var sku by remember{mutableStateOf("")};var name by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};var minStock by remember{mutableStateOf("0")};var category by remember{mutableStateOf<Category?>(null)};var unit by remember{mutableStateOf<UnitRow?>(units.firstOrNull())};var saving by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};ModalBottomSheet(onDismissRequest=onClose,containerColor=Color.White){Column(Modifier.fillMaxWidth().padding(18.dp)){Text("Produk Baru",color=Navy,fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text("Disimpan langsung ke Supabase",color=Text2,fontSize=11.sp,modifier=Modifier.padding(top=3.dp,bottom=12.dp));OutlinedTextField(sku,{sku=it},Modifier.fillMaxWidth(),singleLine=true,label={Text("SKU")});OutlinedTextField(name,{name=it},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,label={Text("Nama produk")});OutlinedTextField(price,{price=it.filter(Char::isDigit)},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Number),label={Text("Harga jual")});OutlinedTextField(minStock,{minStock=it.filter{c->c.isDigit()||c=='.'}},Modifier.fillMaxWidth().padding(top=8.dp),singleLine=true,label={Text("Minimum stok")});Row(Modifier.fillMaxWidth().padding(top=10.dp),horizontalArrangement=Arrangement.spacedBy(7.dp)){categories.forEach{c->FilterChip(selected=category?.id==c.id,onClick={category=c},label={Text(c.name,fontSize=10.sp)})}};Text("Unit",color=Text2,fontSize=11.sp,modifier=Modifier.padding(top=10.dp));Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){units.forEach{u->FilterChip(selected=unit?.id==u.id,onClick={unit=u},label={Text(u.symbol?:u.name,fontSize=10.sp)})}};if(error!=null)Text(error!!,color=Red,fontSize=11.sp,modifier=Modifier.padding(top=8.dp));Button(enabled=!saving&&business!=null&&unit!=null&&sku.isNotBlank()&&name.isNotBlank()&&price.isNotBlank(),onClick={saving=true;CoroutineScopeHolder.launch{runCatching{val b=business!!;val u=unit!!;val newId=UUID.randomUUID().toString();v3Client.from("products").insert(buildJsonObject{put("id",newId);put("business_id",b.id);put("sku",sku.trim());put("name",name.trim());put("category_id",category?.id);put("base_unit_id",u.id);put("product_type","GOODS");put("min_stock",minStock.toDoubleOrNull()?:0.0);put("reorder_point",minStock.toDoubleOrNull()?:0.0);put("is_active",true)});val pl=v3Client.from("price_lists").select{filter{eq("business_id",b.id);eq("is_default",true);eq("is_active",true)}}.decodeList<PriceList>().first();v3Client.from("product_prices").insert(buildJsonObject{put("price_list_id",pl.id);put("product_id",newId);put("unit_id",u.id);put("min_qty",1);put("price",price.toLong())});onSaved()}.onFailure{error=it.message};saving=false}},Modifier.fillMaxWidth().height(52.dp).padding(top=12.dp),shape=RoundedCornerShape(14.dp)){Text(if(saving)"Menyimpan..." else "Simpan Produk",fontWeight=FontWeight.Bold)}}}

@Composable private fun StockV3(){var products by remember{mutableStateOf<List<Product>>(emptyList())};var stock by remember{mutableStateOf<List<Stock>>(emptyList())};LaunchedEffect(Unit){while(true){runCatching{products=v3Client.from("products").select{filter{eq("is_active",true)}}.decodeList<Product>();stock=v3Client.from("stock_balances").select().decodeList<Stock>()};delay(5000)}};V3Shell("Stok","Ketersediaan stok live",{stock=stock}){LazyColumn{items(products){p->val rows=stock.filter{it.product_id==p.id};val qty=rows.sumOf{it.qty_base};val low=qty<=p.min_stock;Card(Modifier.fillMaxWidth().padding(vertical=4.dp),shape=RoundedCornerShape(15.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(p.name,color=Navy,fontWeight=FontWeight.Bold);Text(p.sku,color=Text2,fontSize=10.sp)};Text("${qty.toInt()}",color=if(low)Amber else Navy,fontSize=20.sp,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.width(9.dp));if(low)BadgeV3("LOW")}}}}}}

