@Composable private fun ReportsV3(){var sales by remember{mutableStateOf<List<SaleRow>>(emptyList())};LaunchedEffect(Unit){while(true){runCatching{sales=v3Client.from("sales").select().decodeList<SaleRow>()};delay(5000)}};val completed=sales.filter{it.status.uppercase()=="COMPLETED"};V3Shell("Laporan","Ringkasan penjualan live",{sales=sales}){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){StatV3("Omzet",idr(completed.sumOf{it.total_amount}),"seluruh transaksi selesai",Modifier.weight(1f));StatV3("Transaksi",completed.size.toString(),"selesai",Modifier.weight(1f));StatV3("Rata-rata",idr(if(completed.isEmpty())0 else completed.sumOf{it.total_amount}/completed.size),"per transaksi",Modifier.weight(1f))};Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(17.dp)){Column(Modifier.padding(15.dp)){Text("Ringkasan terbaru",color=Navy,fontWeight=FontWeight.ExtraBold);completed.takeLast(12).reversed().forEach{s->Row(Modifier.fillMaxWidth().padding(vertical=7.dp)){Text(s.sale_no,Modifier.weight(1f),color=Navy);Text(idr(s.total_amount),color=Navy,fontWeight=FontWeight.SemiBold)}}}}}}
