@Composable private fun SettingsV3(){var business by remember{mutableStateOf<BusinessFull?>(null)};var branches by remember{mutableStateOf<List<Branch>>(emptyList())};var locations by remember{mutableStateOf<List<Location>>(emptyList())};var methods by remember{mutableStateOf<List<PaymentMethod>>(emptyList())};var qris by remember{mutableStateOf<List<QrisConfig>>(emptyList())};LaunchedEffect(Unit){while(true){runCatching{business=v3Client.from("businesses").select{filter{eq("is_active",true)}}.decodeList<BusinessFull>().firstOrNull();branches=v3Client.from("branches").select().decodeList<Branch>();locations=v3Client.from("locations").select().decodeList<Location>();methods=v3Client.from("payment_methods").select().decodeList<PaymentMethod>();qris=v3Client.from("qris_configurations").select().decodeList<QrisConfig>()};delay(5000)}};V3Shell("Pengaturan","Konfigurasi bisnis yang tersimpan di Supabase",{business=business}){SettingGroupV3("Bisnis"){Text(business?.name?:"Memuat...",color=Navy,fontWeight=FontWeight.ExtraBold);Text("Kode: ${business?.code?:"-"}",color=Text2,fontSize=11.sp);Text("Mata uang: ${business?.currency_code?:"IDR"}",color=Text2,fontSize=11.sp)};SettingGroupV3("Cabang & lokasi"){branches.forEach{Text("${it.code} • ${it.name}",color=Navy,fontWeight=FontWeight.SemiBold)};locations.forEach{Text("  ${it.code} • ${it.name}",color=Text2,fontSize=11.sp)}};SettingGroupV3("Metode pembayaran"){methods.forEach{Row(Modifier.fillMaxWidth().padding(vertical=5.dp),horizontalArrangement=Arrangement.SpaceBetween){Text(it.name,color=Navy);BadgeV3(it.method_type)}}};SettingGroupV3("QRIS"){qris.forEach{Text("${it.display_name} • ${it.provider} • ${it.mode}",color=Navy,fontWeight=FontWeight.SemiBold);Text("NMID: ${it.nmid?:"-"}",color=Text2,fontSize=11.sp)}}}}
@Composable private fun SettingGroupV3(title:String,content:@Composable ColumnScope.()->Unit){Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(17.dp)){Column(Modifier.padding(15.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text(title,color=Navy,fontWeight=FontWeight.ExtraBold,fontSize=14.sp);content()}}}

@kotlinx.serialization.Serializable data class UnitRow(val id:String,val business_id:String,val code:String,val name:String,val symbol:String?=null)
@kotlinx.serialization.Serializable data class SupplierRow(val id:String,val business_id:String,val code:String,val name:String,val phone:String?=null,val is_active:Boolean=true)
@kotlinx.serialization.Serializable data class PurchaseRow(val id:String,val business_id:String,val branch_id:String,val supplier_id:String,val order_no:String,val order_date:String,val status:String,val total_amount:Long=0)
@kotlinx.serialization.Serializable data class ReceivableRow(val id:String,val business_id:String,val branch_id:String,val customer_id:String,val sale_id:String?=null,val invoice_no:String,val invoice_date:String,val due_date:String,val original_amount:Long,val paid_amount:Long=0,val outstanding_amount:Long=0,val status:String)
@kotlinx.serialization.Serializable data class PaymentRow(val id:String,val business_id:String,val branch_id:String,val sale_id:String?=null,val payment_method_id:String,val payment_no:String,val amount:Long,val status:String,val provider:String?=null)
@kotlinx.serialization.Serializable data class BusinessFull(val id:String,val code:String,val name:String,val currency_code:String="IDR",val timezone:String="Asia/Jakarta")

private fun kotlinx.serialization.json.JsonObject.Companion.dummy() = buildJsonObject {}
private fun kotlinx.serialization.json.buildJsonArrayCompatHack() = kotlinx.serialization.json.buildJsonArray {}
